# Improper Use of Java API - SQL Injection Vulnerability

Here's a demonstration of a vulnerable code snippet followed by the secure version:

```java
import java.sql.*;
import javax.servlet.http.*;

public class UserLoginVulnerable {

    // This method is vulnerable to SQL injection attacks
    // The user input is directly concatenated into the SQL query
    public boolean authenticateUser(HttpServletRequest request, Connection conn) {
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        try {
            // DANGEROUS: Direct string concatenation makes this vulnerable to SQL injection
            // An attacker could input: ' OR '1'='1' -- 
            String query = "SELECT * FROM users WHERE username = '" + username + 
                          "' AND password = '" + password + "'";

            // Using Statement instead of PreparedStatement is insecure
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);  // Executes potentially malicious SQL

            return rs.next();  // Returns true if any row is found
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }
}
```

***

```java
import java.sql.*;
import javax.servlet.http.*;

public class UserLoginSecure {

    // This method properly uses PreparedStatement to prevent SQL injection
    // Parameterized queries ensure user input is treated as data, not code
    public boolean authenticateUser(HttpServletRequest request, Connection conn) {
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        // Use a parameterized query with placeholders (?)
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        try {
            // PreparedStatement safely handles user input by escaping special characters
            PreparedStatement pstmt = conn.prepareStatement(query);

            // Bind parameters - the API automatically sanitizes the input
            pstmt.setString(1, username);  // First placeholder
            pstmt.setString(2, password);  // Second placeholder

            // Execute the safe, parameterized query
            ResultSet rs = pstmt.executeQuery();

            boolean authenticated = rs.next();

            // Always close resources properly
            rs.close();
            pstmt.close();

            return authenticated;
        } catch (SQLException e) {
            // Log the error securely without exposing sensitive information
            System.err.println("Authentication error occurred");
            return false;
        }
    }
}
```

